-- Initial schema for the whole application
--
-- Conventions (see Database.md): snake_case, plural table names, `uuid` ids generated by the application (no database
-- default), timestamps as timestamptz (UTC), dates as date, hard deletes, explicit constraint and index names:
--   pk_<table>, fk_<table>__<referenced_table>, uq_<table>__<column>, ix_<table>__<column>
-- Value rules (lengths, ranges, allowed values) are validated by the server, not by CHECK constraints.
-- Strings have explicit lengths sized to their content; only free text (descriptions) is `text`.

-- ---------------------------------------------------------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE users
(
    id             uuid          NOT NULL,
    email          varchar(255)  NOT NULL,
    email_verified boolean       NOT NULL DEFAULT false,
    pending_email  varchar(255),
    password_hash  varchar(255)  NOT NULL, -- BCrypt today; the headroom allows a longer hash format later
    display_name   varchar(255)  NOT NULL,
    avatar_url     varchar(2048),
    timezone       varchar(64)   NOT NULL, -- IANA identifier, e.g. Europe/Berlin
    created_at     timestamptz   NOT NULL,
    updated_at     timestamptz   NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id)
);

-- Case-insensitive uniqueness: "Ann@x.com" and "ann@x.com" are the same account.
CREATE UNIQUE INDEX uq_users__email ON users (lower(email));

-- ---------------------------------------------------------------------------------------------------------------------
-- calendars
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE calendars
(
    id         uuid         NOT NULL,
    user_id    uuid         NOT NULL,
    name       varchar(40)  NOT NULL,
    color      varchar(7)   NOT NULL, -- #RRGGBB
    icon       varchar(20)  NOT NULL, -- CalendarIcon
    position   integer      NOT NULL,
    is_default boolean      NOT NULL DEFAULT false,
    created_at timestamptz  NOT NULL,
    updated_at timestamptz  NOT NULL,
    CONSTRAINT pk_calendars PRIMARY KEY (id),
    CONSTRAINT fk_calendars__users FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

-- A calendar name is unique per user, case-insensitively.
CREATE UNIQUE INDEX uq_calendars__user_id_name ON calendars (user_id, lower(name));

-- At most one default calendar per user (the application guarantees there is exactly one).
CREATE UNIQUE INDEX uq_calendars__user_id_default ON calendars (user_id) WHERE is_default;

-- ---------------------------------------------------------------------------------------------------------------------
-- recurrence_rules (the RecurrenceRule value object, referenced by events and tasks)
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE recurrence_rules
(
    id           uuid        NOT NULL,
    frequency    varchar(10) NOT NULL, -- DAILY, WEEKLY, MONTHLY, YEARLY
    interval     integer     NOT NULL DEFAULT 1,
    by_day       varchar(20),          -- comma-separated ISO day codes, e.g. MO,WE,FR (weekly only): at most 7 x 2 + 6
    by_month_day integer,              -- monthly only
    end_type     varchar(16) NOT NULL, -- NEVER, UNTIL, AFTER_COUNT
    until        date,                 -- if UNTIL; inclusive, in the item's time zone
    count        integer,              -- if AFTER_COUNT
    CONSTRAINT pk_recurrence_rules PRIMARY KEY (id)
);

-- ---------------------------------------------------------------------------------------------------------------------
-- events
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE events
(
    id                 uuid         NOT NULL,
    user_id            uuid         NOT NULL,
    calendar_id        uuid,
    recurrence_rule_id uuid, -- NULL means "not recurring"
    title              varchar(120) NOT NULL,
    description        text,
    location           varchar(255),
    starts_at          timestamptz  NOT NULL,
    ends_at            timestamptz  NOT NULL,
    timezone           varchar(64)  NOT NULL,
    all_day           boolean      NOT NULL DEFAULT false,
    created_at         timestamptz  NOT NULL,
    updated_at         timestamptz  NOT NULL,
    CONSTRAINT pk_events PRIMARY KEY (id),
    CONSTRAINT fk_events__users FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    -- Safety net matching the default "unassign" mode of calendar deletion.
    CONSTRAINT fk_events__calendars FOREIGN KEY (calendar_id) REFERENCES calendars (id) ON DELETE SET NULL,
    CONSTRAINT fk_events__recurrence_rules FOREIGN KEY (recurrence_rule_id) REFERENCES recurrence_rules (id) ON DELETE SET NULL
);

-- Range queries for non-recurring events.
CREATE INDEX ix_events__user_id_starts_at ON events (user_id, starts_at);
-- Finding the series to expand; stays small because it only holds recurring events.
CREATE INDEX ix_events__user_id_recurring ON events (user_id, starts_at) WHERE recurrence_rule_id IS NOT NULL;
-- Foreign keys: item counts per calendar, and ON DELETE SET NULL of calendars and recurrence rules.
CREATE INDEX ix_events__calendar_id ON events (calendar_id);
CREATE INDEX ix_events__recurrence_rule_id ON events (recurrence_rule_id);

-- ---------------------------------------------------------------------------------------------------------------------
-- event_preparation_steps (an event's routine)
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE event_preparation_steps
(
    id       uuid         NOT NULL, -- storage-only surrogate key, never exposed by the API
    event_id uuid         NOT NULL,
    name     varchar(255) NOT NULL,
    duration integer      NOT NULL, -- minutes
    position integer      NOT NULL, -- 0-based order in the sequence
    CONSTRAINT pk_event_preparation_steps PRIMARY KEY (id),
    CONSTRAINT fk_event_preparation_steps__events FOREIGN KEY (event_id) REFERENCES events (id) ON DELETE CASCADE
);

CREATE INDEX ix_event_preparation_steps__event_id_position ON event_preparation_steps (event_id, position);

-- ---------------------------------------------------------------------------------------------------------------------
-- tasks
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE tasks
(
    id                 uuid         NOT NULL,
    user_id            uuid         NOT NULL,
    calendar_id        uuid,
    recurrence_rule_id uuid, -- NULL means "not recurring"
    title              varchar(120) NOT NULL,
    description        text,
    due_at             timestamptz,
    scheduled_for      date,
    scheduled_start_at timestamptz,
    scheduled_end_at   timestamptz,
    timezone           varchar(64)  NOT NULL,
    completed         boolean      NOT NULL DEFAULT false,
    completed_at       timestamptz,
    position           integer      NOT NULL DEFAULT 0,
    created_at         timestamptz  NOT NULL,
    updated_at         timestamptz  NOT NULL,
    CONSTRAINT pk_tasks PRIMARY KEY (id),
    CONSTRAINT fk_tasks__users FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_tasks__calendars FOREIGN KEY (calendar_id) REFERENCES calendars (id) ON DELETE SET NULL,
    CONSTRAINT fk_tasks__recurrence_rules FOREIGN KEY (recurrence_rule_id) REFERENCES recurrence_rules (id) ON DELETE SET NULL
);

CREATE INDEX ix_tasks__user_id_scheduled_for ON tasks (user_id, scheduled_for); -- My Day / This Week
CREATE INDEX ix_tasks__user_id_due_at ON tasks (user_id, due_at);               -- Due and Overdue
CREATE INDEX ix_tasks__user_id_completed ON tasks (user_id, completed, completed_at); -- Completed view and streak
-- Foreign keys: item counts per calendar, and ON DELETE SET NULL of calendars and recurrence rules.
CREATE INDEX ix_tasks__calendar_id ON tasks (calendar_id);
CREATE INDEX ix_tasks__recurrence_rule_id ON tasks (recurrence_rule_id);

-- ---------------------------------------------------------------------------------------------------------------------
-- task_completions (per-occurrence completion of recurring tasks)
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE task_completions
(
    task_id         uuid        NOT NULL,
    occurrence_date date        NOT NULL,
    completed_at    timestamptz NOT NULL,
    CONSTRAINT pk_task_completions PRIMARY KEY (task_id, occurrence_date),
    CONSTRAINT fk_task_completions__tasks FOREIGN KEY (task_id) REFERENCES tasks (id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------------------------------------------------------
-- recurrence_exceptions (overrides and skips of single occurrences)
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE recurrence_exceptions
(
    id                 uuid    NOT NULL,
    event_id           uuid,   -- exactly one of event_id / task_id is set (enforced by the server)
    task_id            uuid,
    occurrence_date    date    NOT NULL,
    skipped            boolean NOT NULL DEFAULT false,
    -- Overrides. NULL means "not overridden".
    title              varchar(120),
    description        text,
    -- Event-only overrides
    location           varchar(255),
    starts_at          timestamptz,
    ends_at            timestamptz,
    all_day            boolean,
    routine_override   jsonb,
    -- Task-only overrides
    due_at             timestamptz,
    scheduled_for      date,
    scheduled_start_at timestamptz,
    scheduled_end_at   timestamptz,
    CONSTRAINT pk_recurrence_exceptions PRIMARY KEY (id),
    CONSTRAINT fk_recurrence_exceptions__events FOREIGN KEY (event_id) REFERENCES events (id) ON DELETE CASCADE,
    CONSTRAINT fk_recurrence_exceptions__tasks FOREIGN KEY (task_id) REFERENCES tasks (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX uq_recurrence_exceptions__event_id_occurrence_date
    ON recurrence_exceptions (event_id, occurrence_date) WHERE event_id IS NOT NULL;
CREATE UNIQUE INDEX uq_recurrence_exceptions__task_id_occurrence_date
    ON recurrence_exceptions (task_id, occurrence_date) WHERE task_id IS NOT NULL;

-- ---------------------------------------------------------------------------------------------------------------------
-- refresh_tokens (only hashes are stored; see Security.md)
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE refresh_tokens
(
    id         uuid        NOT NULL,
    user_id    uuid        NOT NULL,
    family_id  uuid        NOT NULL, -- all tokens descending from one login share a family
    token_hash varchar(64) NOT NULL, -- SHA-256, hex encoded
    created_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz,          -- set on rotation, logout and family revocation
    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id),
    CONSTRAINT fk_refresh_tokens__users FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX uq_refresh_tokens__token_hash ON refresh_tokens (token_hash);
-- Revoking every token of a user (password change/reset, account deletion).
CREATE INDEX ix_refresh_tokens__user_id ON refresh_tokens (user_id);
-- Revoking a whole family on reuse detection.
CREATE INDEX ix_refresh_tokens__family_id ON refresh_tokens (family_id);

-- ---------------------------------------------------------------------------------------------------------------------
-- one_time_tokens (email verification and password reset; only hashes are stored)
-- ---------------------------------------------------------------------------------------------------------------------
CREATE TABLE one_time_tokens
(
    id         uuid         NOT NULL,
    user_id    uuid         NOT NULL,
    purpose    varchar(20)  NOT NULL, -- VERIFY_EMAIL, RESET_PASSWORD
    token_hash varchar(64)  NOT NULL, -- SHA-256, hex encoded
    email      varchar(255) NOT NULL, -- the address the token concerns
    created_at timestamptz  NOT NULL,
    expires_at timestamptz  NOT NULL,
    used_at    timestamptz,
    CONSTRAINT pk_one_time_tokens PRIMARY KEY (id),
    CONSTRAINT fk_one_time_tokens__users FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX uq_one_time_tokens__token_hash ON one_time_tokens (token_hash);
-- A new token invalidates the user's previous ones of the same purpose.
CREATE INDEX ix_one_time_tokens__user_id_purpose ON one_time_tokens (user_id, purpose);
